arguments.file_text:
@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="mb-3">
    <button class="btn btn-primary" @onclick="ShowCreateForm">
        @(showForm ? "Cancel" : "New Shipment")
    </button>
</div>

@if (showForm)
{
    <div class="card mb-4 p-3">
        <h4>Create Shipment</h4>
        <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="CreateShipment">
            <DataAnnotationsValidator />
            <div class="row g-3">
                <div class="col-md-4">
                    <label class="form-label">Origin</label>
                    <InputText @bind-Value="newShipment.Origin" class="form-control" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Destination</label>
                    <InputText @bind-Value="newShipment.Destination" class="form-control" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Customer Email</label>
                    <InputText @bind-Value="newShipment.CustomerEmail" class="form-control" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Description</label>
                    <InputText @bind-Value="newShipment.Description" class="form-control" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Estimated Delivery</label>
                    <InputDate @bind-Value="newShipment.EstimatedDelivery" class="form-control" />
                </div>
                <div class="col-12">
                    <button type="submit" class="btn btn-success">Create</button>
                </div>
            </div>
        </EditForm>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td><code>@s.TrackingNumber</code></td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge bg-@GetStatusColor(s.Status)">@s.Status</span></td>
                    <td>@s.ShippedDate.ToShortDateString()</td>
                    <td>@s.EstimatedDelivery.ToShortDateString()</td>
                    <td>
                        <select class="form-select form-select-sm" value="@s.Status"
                                @onchange="e => UpdateStatus(s, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private Shipment newShipment = new() { EstimatedDelivery = DateTime.Today.AddDays(5) };
    private bool showForm;
    private string filterText = string.Empty;

    private IEnumerable<Shipment> FilteredShipments => shipments!
        .Where(s => string.IsNullOrEmpty(filterText)
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showForm = !showForm;

    private async Task CreateShipment()
    {
        newShipment.ShippedDate = DateTime.UtcNow;
        newShipment.Status = ShipmentStatus.Pending;
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments!.Insert(0, created);
        newShipment = new() { EstimatedDelivery = DateTime.Today.AddDays(5) };
        showForm = false;
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, status);
            shipment.Status = status;
        }
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Track My Shipments</PageTitle>

<h1>Track Shipments</h1>

<div class="card mb-4 p-3">
    <h5>Look up by Tracking Number</h5>
    <div class="input-group">
        <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-20260701-123456)"
               @bind="trackingInput" @bind:event="oninput" @onkeydown="HandleKeyDown" />
        <button class="btn btn-outline-primary" @onclick="SearchByTracking">Search</button>
    </div>
    @if (searchError is not null)
    {
        <div class="alert alert-warning mt-2">@searchError</div>
    }
</div>

@if (trackedShipment is not null)
{
    <div class="card mb-4 p-3">
        <h5>Shipment Details</h5>
        <dl class="row mb-0">
            <dt class="col-sm-3">Tracking #</dt>
            <dd class="col-sm-9"><code>@trackedShipment.TrackingNumber</code></dd>
